-- D-B2-08: every key whose change needs an approval (the TEN registry pins it against approverPermission).
CREATE OR REPLACE FUNCTION approval_setting_keys() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT ARRAY['money.rounding_mode', 'money.clawback_policy', 'genealogy.visibility_policy', 'payouts.market_policy',
               'payouts.bank_detail_cooling_off_hours', 'adjustments.policy', 'write_offs.policy', 'privacy.policy',
               'portal.customer_contact_visible']
$$;
